**Consent Screen UI**
```javascript
// components/Onboarding/ConsentScreen.js
import React, { useState } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, Switch } from 'react-native';

const ConsentScreen = ({ navigation }) => {
  const [consents, setConsents] = useState({
    privacy: false,
    resources: false,
    location: false,
    ble: false
  });

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Privacy & Permissions</Text>
      <Text style={styles.subtitle}>We need your consent to use unused device resources</Text>

      <View style={styles.consentList}>
        {[
          {
            key: 'privacy',
            title: 'Privacy Policy',
            desc: 'Data handling and security practices'
          },
          {
            key: 'resources', 
            title: 'Device Resources',
            desc: 'Use NPU, storage, memory when idle'
          },
          {
            key: 'location',
            title: 'Location Tracking',
            desc: 'GPS for missions and gravity wells'
          },
          {
            key: 'ble',
            title: 'BLE Scanning',
            desc: 'Detect beacons and IoT devices'
          }
        ].map((consent) => (
          <View key={consent.key} style={styles.consentItem}>
            <View style={styles.consentText}>
              <Text style={styles.consentTitle}>{consent.title}</Text>
              <Text style={styles.consentDesc}>{consent.desc}</Text>
            </View>
            <Switch
              value={consents[consent.key]}
              onValueChange={() => {
                const newConsents = { ...consents, [consent.key]: !consents[consent.key] };
                setConsents(newConsents);
              }}
              trackColor={{ false: '#4A4A64', true: '#00CECB' }}
              thumbColor={consents[consent.key] ? '#FFFFFF' : '#F5F5F5'}
            />
          </View>
        ))}
      </View>

      <TouchableOpacity 
        style={[styles.primaryButton, !Object.values(consents).every(c => c) && styles.disabledButton]}
        disabled={!Object.values(consents).every(c => c)}
        onPress={() => navigation.navigate('DeviceCheck')}
      >
        <Text style={styles.buttonText}>Continue</Text>
      </TouchableOpacity>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#1A1A2E',
    padding: 20
  },
  title: {
    fontSize: 28,
    fontWeight: 'bold',
    color: '#FFFFFF',
    marginTop: 20,
    marginBottom: 10
  },
  subtitle: {
    fontSize: 16,
    color: '#B0B0C8'
  },
