  const [resources, setResources] = useState(null);
  const [isContributing, setIsContributing] = useState(false);

  useEffect(() => {
    loadResources();
    const interval = setInterval(loadResources, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const loadResources = async () => {
    // In real implementation, fetch from device APIs and API
    setResources({
      npu: { capacity: 85, usage: 'high', status: 'available' },
      storage: { available: '2.5 GB', used: '1.5 GB', usage: 'medium', status: 'available' },
      memory: { free: '3.2 GB', total: '8 GB', usage: 'low', status: 'available' },
      battery: { level: 75, status: 'good', charging: false }
    });
  };

  const handleContribute = (resourceType) => {
    Alert.alert(
      `Contribute ${resourceType}?`,
      "Your device will use this resource for distributed computing when idle.",
      [
        { text: "Cancel", style: "cancel" },
        { 
          text: "Start Contributing", 
          onPress: () => startContribution(resourceType)
        }
      ]
    );
  };

  const startContribution = (resourceType) => {
    setIsContributing(true);

    // In real implementation, start resource contribution process
    Alert.alert(
      "Resource Contribution Started",
      `${resourceType} will be contributed when your device is idle.`,
      [{ text: "OK", onPress: () => setIsContributing(false) }]
    );
  };

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity 
          style={styles.backButton}
          onPress={() => navigation.goBack()}
        >
          <Text style={styles.backArrow}>â†�</Text>
          <Text style={styles.backText}>Back to Dashboard</Text>
        </TouchableOpacity>

        {isContributing && (
          <View style={styles.contributionIndicator}>
            <Text style={styles.contributionIcon}>âš¡</Text>
            <Text style={styles.contributionText}>Contributing Resources Now</Text>
            <TouchableOpacity 
              style={styles.stopButton}
              onPress={() => setIsContributing(false)}
            >
              <Text style={styles.stopButtonText}>Stop</Text>
            </TouchableOpacity>
          </View>
        )}
      </View>

      {/* Content */}
      <ScrollView style={styles.content}>
        {/* NPU Section */}
        <View style={styles.resourceSection}>
          <View style={styles.sectionHeader}>
            <Text style={styles.sectionTitle}>ðŸ§  Neural Processing Unit</Text>
