// screens/CreativeEngineScreen.js
import React, { useState } from 'react';
import { View, Text, StyleSheet, ScrollView, TextInput, TouchableOpacity, Alert } from 'react-native';

const CreativeEngineScreen = ({ navigation }) => {
  const [prompt, setPrompt] = useState('');
  const [outputType, setOutputType] = useState('code');
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState(null);

  const handleGenerate = async () => {
    if (!prompt.trim()) {
      Alert.alert('Error', 'Please enter a creative prompt first');
      return;
    }

    setIsGenerating(true);

    // In real implementation, call the creative API
    try {
      const response = await fetch('https://api.sovereign-spacebook.com/v1/creative/generate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer YOUR_JWT_TOKEN'
        },
        body: JSON.stringify({
          prompt,
          options: { quality: outputType === 'code' ? 'high' : 'medium' }
        })
      });

      const data = await response.json();

      if (data.creative_id) {
        setResult(data);
      } else {
        Alert.alert('Generation Failed', 'Please try again later');
      }
    } catch (error) {
      Alert.alert('Error', 'Failed to connect to creative engine');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity 
          style={styles.backButton}
          onPress={() => navigation.goBack()}
        >
          <Text style={styles.backArrow}>â†�</Text>
          <Text style={styles.backText}>Back to Dashboard</Text>
        </TouchableOpacity>

