// services/apiService.js
import AsyncStorage from '@react-native-async-storage/async-storage';

const API_BASE_URL = 'https://api.sovereign-spacebook.com/v1';

class ApiService {
  async makeRequest(endpoint, options = {}) {
    const token = await AsyncStorage.getItem('jwt_token');

    const headers = {
      'Content-Type': 'application/json',
      ...options.headers
    };

    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    try {
      const response = await fetch(`${API_BASE_URL}${endpoint}`, {
        ...options,
        headers
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('API Request Error:', error);
      throw error;
    }
  }

  async getProfile() {
    return this.makeRequest('/auth/profile');
  }

  async contributeResources(durationSeconds, resourceTypes) {
    return this.makeRequest('/resources/contribute', {
      method: 'POST',
      body: JSON.stringify({ duration_seconds: durationSeconds, resource_types: resourceTypes })
    });
  }
}

export default new ApiService();
