```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

contract Spacecoin is ERC20, Ownable, Pausable {
    // Token constants
    uint8 public constant DECIMALS = 18;
    string public constant NAME = "Spacebook Coin";
    string public constant SYMBOL = "SPC";

    // Minting and burning controls
    bool public mintingPaused = false;

    // Initial distribution allocations
    mapping(address => bool) public hasReceivedInitialReward;
    uint256 public constant INITIAL_REWARD_AMOUNT = 500 * (10 ** DECIMALS);

    // Resource contribution multipliers
    struct ContributionMultiplier {
        uint248 npuMultiplier;      // 1.0x to 1000x multiplier (scaled by 100)
        uint248 storageMultiplier;  // 1.0x to 1000x multiplier (scaled by 100)
    }

    mapping(address => ContributionMultiplier) public contributionMultipliers;

    // Events
    event InitialRewardMinted(address indexed account, uint256 amount);
    event ResourceContributionUpdated(address indexed account, string resourceType, uint256 multiplier);
    event RewardClaimed(address indexed account, uint256 amount, string rewardType);

    constructor() ERC20(NAME, SYMBOL) {
        // Deployer gets initial token supply management role
        _mint(msg.sender, 1_000_000_000 * (10 ** DECIMALS));
    }

    /**
     * @notice Mint initial reward tokens to new users
     * @param account The account to receive the reward
     */
    function mintInitialReward(address account) external whenNotPaused {
        require(!hasReceivedInitialReward[account], "Already received initial reward");

        hasReceivedInitialReward[account] = true;
        _mint(account, INITIAL_REWARD_AMOUNT);

        emit InitialRewardMinted(account, INITIAL_REWARD_AMOUNT);
    }

    /**
     * @notice Update contribution multiplier for a specific resource type
     * @param account The account to update multiplier for
     * @param resourceType Type of resource (NPU, storage, memory)
     * @param multiplier New multiplier value (scaled by 100)
     */
    function updateContributionMultiplier(address account, string calldata resourceType, uint256 multiplier) external onlyOwner {
        ContributionMultiplier storage mult = contributionMultipliers[account];

        if (keccak256(abi.encodePacked(resourceType)) == keccak256(abi.encodePacked("NPU"))) {
            mult.npuMultiplier = uint248(multiplier);
            emit ResourceContributionUpdated(account, resourceType, multiplier);
        } else if (keccak256(abi.encodePacked(resourceType)) == keccak256(abi.encodePacked("Storage"))) {
            mult.storageMultiplier = uint248(multiplier);
            emit ResourceContributionUpdated(account, resourceType, multiplier);
        }
    }

    /**
     * @notice Calculate reward amount based on contribution and multipliers
     * @param baseAmount Base reward amount before multipliers
     * @param account Account to calculate reward for
     * @return Calculated reward with multipliers applied
     */
    function calculateRewardWithMultiplier(uint256 baseAmount, address account) external view returns (uint256) {
        ContributionMultiplier memory mult = contributionMultipliers[account];

        // Apply NPU multiplier first (if applicable)
        uint256 adjustedAmount = baseAmount * mult.npuMultiplier / 100;

        // Then apply storage multiplier
        return adjustedAmount * mult.storageMultiplier / 100;
    }

    /**
     * @notice Pause minting functionality
     */
    function pauseMinting() external onlyOwner {
        mintingPaused = true;
    }

    /**
     * @notice Unpause minting functionality
     */
    function unpauseMinting() external onlyOwner {
        mintingPaused = false;
    }
}
