#### Governance Token (SVC) - Voting and Staking
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/governance/GSN/Context.sol";

contract SpacebookGovernance is ERC20, Ownable {
    // Governance constants
    uint8 public constant DECIMALS = 18;
    string public constant NAME = "Sovereign Mesh Vote Token";
    string public constant SYMBOL = "SVC";

    // Voting parameters
    uint256 public votingDelay = 1 blocks;      // Delay after proposal creation before voting starts
    uint256 public votingPeriod = 40320 blocks; // ~1 week (assuming 15s block time)
    uint256 public proposalThreshold = 1000 * (10 ** DECIMALS); // Tokens needed to create proposals

    // Proposal structure
    struct Proposal {
        uint256 id;
        address proposer;
        string description;
        uint256 creationBlock;
        uint256 startVoteBlock;
        uint256 endVoteBlock;
        bool executed;
        mapping(address => Vote) votes; // Voter -> Weighted vote
    }

    enum Vote { Abstain, Yes, No }

    Proposal[] public proposals;
    mapping(uint256 => address[]) public proposalVotes; // Proposal ID -> voters list

    // Staking parameters
    uint256 public stakingPeriod = 30 days; // Minimum staking period
    uint256 public unstakingPenalty = 10;   // 10% penalty for early unstaking

    event ProposalCreated(uint256 indexed proposalId, address proposer, string description);
    event VoteCast(address indexed voter, uint256 indexed proposalId, Vote vote);
    event ProposalExecuted(uint256 indexed proposalId);

    constructor() ERC20(NAME, SYMBOL) {
        // Deployer gets governance token supply management role
        _mint(msg.sender, 100_000_000 * (10 ** DECIMALS));
    }

    /**
     * @notice Create a new proposal
     * @param description Description of the proposal
     */
    function createProposal(string memory description) external {
        require(balanceOf(msg.sender) >= proposalThreshold, "Not enough tokens to create proposal");

        uint256 proposalId = proposals.length;

        proposals.push(Proposal({
            id: proposalId,
            proposer: msg.sender,
            description: description,
            creationBlock: block.number,
            startVoteBlock: block.number + votingDelay,
            endVoteBlock: block.number + votingDelay + votingPeriod,
            executed: false
        }));

        emit ProposalCreated(proposalId, msg.sender, description);
    }

    /**
     * @notice Vote on a proposal
     * @param proposalId ID of the proposal to vote on
     * @param vote The vote (Abstain, Yes, No)
     */
    function vote(uint256 proposalId, Vote vote) external {
        require(proposals[proposalId].creationBlock < block.number, "Proposal not yet created");
        require(block.number >= proposals[proposalId].startVoteBlock, "Voting hasn't started yet");
        require(block.number <= proposals[proposalId].endVoteBlock, "Voting has ended");

        uint256 voteWeight = balanceOf(msg.sender);

        if (proposals[proposalId].votes[msg.sender] == Vote.Abstain) {
            // First vote - use full balance
            proposalVotes[proposalId].push(msg.sender);
        } else {
            // Update existing vote weight
            voteWeight = voteWeight - proposals[proposalId].votes[msg.sender];
        }

        proposals[proposalId].votes[msg.sender] = vote;

        emit VoteCast(msg.sender, proposalId, vote);
    }

    /**
     * @notice Execute a proposal if it has been approved
     * @param proposalId ID of the proposal to execute
     */
    function executeProposal(uint256 proposalId) external {
        Proposal storage proposal = proposals[proposalId];

        require(!proposal.executed, "Proposal already executed");
        require(block.number > proposal.endVoteBlock, "Voting hasn't ended yet");

        // Count votes
        uint256 yesVotes = 0;
        uint256 noVotes = 0;

        for (uint i = 0; i < proposalVotes[proposalId].length; i++) {
            address voter = proposalVotes[proposalId][i];

            if (proposal.votes[voter] == Vote.Yes) {
                yesVotes += balanceOf(voter);
            } else if (proposal.votes[voter] == Vote.No) {
                noVotes += balanceOf(voter);
            }
        }

        require(yesVotes > noVotes, "Proposal not approved");

        // Execute proposal logic would go here
        proposal.executed = true;

        emit ProposalExecuted(proposalId);
    }

    /**
     * @notice Stake SVC tokens for voting power and rewards
     * @param amount Amount of tokens to stake
     */
    function stake(uint256 amount) external {
        // Transfer tokens from user
        transferFrom(msg.sender, address(this), amount);

        // Mint staking receipt (simplified)
        _mint(msg.sender, amount);

        // Lock tokens for minimum period (in real implementation would add locking mechanism)
    }

    /**
     * @notice Unstake SVC tokens with penalty if unstaked early
     * @param amount Amount of tokens to unstake
     */
    function unstake(uint256 amount) external {
        // Calculate penalty if unstaking before minimum period (simplified logic)
        uint256 penalty = amount * unstakingPenalty / 100;

        // Burn staking receipt and transfer tokens back
        _burn(msg.sender, amount);
        transfer(msg.sender, amount - penalty);
    }
}
