    }

    // Storage mappings
    mapping(uint256 => ContributionRecord) public contributions;
    mapping(address => UserStats) public userStats;
    mapping(address => uint256[]) public userContributions;  // User -> list of contribution IDs

    // Reward rates per resource type (scaled by 1000)
    mapping(string => uint256) public rewardRates; // Example: NPU = 1000, Storage = 500

    // Events
    event ContributionRecorded(
        address indexed contributor,
        string resourceType,
        uint256 amount,
        uint256 durationSeconds,
        uint256 timestamp
    );
    event RewardDistributed(address indexed user, uint256 amount);

    constructor() {
        // Set default reward rates
        rewardRates["NPU"] = 1000;
        rewardRates["Storage"] = 500;
        rewardRates["Memory"] = 750;
    }

    /**
     * @notice Record a new contribution
     * @param resourceType Type of resource contributed
     * @param amount Amount contributed (scaled by 10^6)
     * @param durationSeconds Duration of contribution in seconds
     */
    function recordContribution(string calldata resourceType, uint256 amount, uint256 durationSeconds) 
        external whenNotPaused {

        // Verify the contribution (in real implementation would verify with off-chain oracles or proofs)
        require(amount > 0, "Amount must be greater than zero");
        require(durationSeconds > 0, "Duration must be greater than zero");

        uint256 contributionId = contributions.length;

        ContributionRecord memory newContribution = ContributionRecord({
            contributor: msg.sender,
            resourceType: resourceType,
            amount: amount,
            timestamp: block.timestamp,
            durationSeconds: durationSeconds,
            verified: false // Would be set to true after off-chain verification
        });

        contributions[contributionId] = newContribution;
        userContributions[msg.sender].push(contributionId);

        // Update user stats
        UserStats storage stats = userStats[msg.sender];
        stats.totalContributions += 1;
        stats.lastContributionTime = block.timestamp;

        emit ContributionRecorded(msg.sender, resourceType, amount, durationSeconds, block.timestamp);
    }

    /**
     * @notice Calculate rewards for a specific contribution
     * @param contributionId ID of the contribution to calculate reward for
     * @return Reward amount in Spacecoin (scaled by 10^6)
     */
    function calculateReward(uint256 contributionId) external view returns (uint256) {
        ContributionRecord memory contrib = contributions[contributionId];

        require(contrib.contributor != address(0), "Invalid contribution ID");

        // Calculate base reward
        uint256 baseReward = (contrib.amount * rewardRates[contrib.resourceType]) / 1000;

        // Apply duration bonus (simplified)
        uint256 durationBonus = baseReward * contrib.durationSeconds / 3600; // Bonus for longer contributions

        return baseReward + durationBonus;
    }

    /**
     * @notice Distribute rewards to contributor
     * @param contributionId ID of the contribution
     */
    function distributeReward(uint256 contributionId) external {
        uint256 reward = calculateReward(contributionId);

        require(reward > 0, "No reward available");

        // In real implementation would transfer from reserve address
        // _transfer(address(reserve), msg.sender, reward);

        // Update user stats
        UserStats storage stats = userStats[msg.sender];
        stats.totalRewardEarned += reward;

        emit RewardDistributed(msg.sender, reward);
    }

    /**
     * @notice Get contribution count for a user
     * @param account User address to check
     * @return Number of contributions made by the user
     */
    function getUserContributionCount(address account) external view returns (uint256) {
        return userContributions[account].length;
    }

    /**
     * @notice Get contribution details for a specific ID
     * @param contributionId ID of the contribution
     * @return Contribution record
     */
    function getContribution(uint256 contributionId) external view returns (
        address contributor,
        string memory resourceType,
        uint256 amount,
        uint256 durationSeconds,
        uint256 timestamp,
        bool verified
    ) {
        ContributionRecord storage contrib = contributions[contributionId];

        return (
            contrib.contributor,
            contrib.resourceType,
            contrib.amount,
            contrib.durationSeconds,
            contrib.timestamp,
            contrib.verified
        );
    }

    /**
     * @notice Set reward rate for a resource type
     * @param resourceType Type of resource
     * @param rate New reward rate (scaled by 1000)
     */
    function setRewardRate(string calldata resourceType, uint256 rate) external onlyOwner {
        rewardRates[resourceType] = rate;
    }
}
