// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

contract SMIdentity is Ownable, Pausable {
    // Identity structure
    struct Identity {
        bytes32 meshId;          // 5D address hash (Sovereign Mesh ID)
        string publicKey;        // User's public key for signing
        uint256 createdAt;
        bool active;
        mapping(string => bytes32) claims;  // Claims about the user
    }

    // Storage mappings
    mapping(address => Identity) public identities;
    mapping(bytes32 => address) public identityToAddress;

    // Events
    event IdentityCreated(address indexed account, bytes32 indexed meshId);
    event ClaimAdded(address indexed account, string claimType, bytes32 claimValue);
    event IdentityRevoked(address indexed account);

    /**
     * @notice Create a new identity for the caller
     * @param meshId The 5D address hash (Sovereign Mesh ID)
     * @param publicKey User's public key for signing transactions
     */
    function createIdentity(bytes32 meshId, string calldata publicKey) external whenNotPaused {
        require(identities[msg.sender].meshId == 0, "Identity already exists");

        Identity storage newIdentity = identities[msg.sender];
        newIdentity.meshId = meshId;
        newIdentity.publicKey = publicKey;
        newIdentity.createdAt = block.timestamp;
        newIdentity.active = true;

        identityToAddress[meshId] = msg.sender;

        emit IdentityCreated(msg.sender, meshId);
    }

    /**
     * @notice Add or update a claim about the user
     * @param claimType Type of claim (e.g., "NPU_CAPABILITY", "LOCATION")
     * @param claimValue Hashed value of the claim
     */
    function addClaim(string calldata claimType, bytes32 claimValue) external {
        require(identities[msg.sender].active, "Identity not active");

        identities[msg.sender].claims[claimType] = claimValue;
        emit ClaimAdded(msg.sender, claimType, claimValue);
    }

    /**
     * @notice Revoke an identity
     */
    function revokeIdentity() external whenNotPaused {
        require(identities[msg.sender].active, "Identity not active");

        identities[msg.sender].active = false;
        delete identityToAddress[identities[msg.sender].meshId];

        emit IdentityRevoked(msg.sender);
    }

    /**
     * @notice Get identity for an address
     * @param account Address to get identity for
     * @return Identity details
     */
    function getIdentity(address account) external view returns (
        bytes32 meshId,
        string memory publicKey,
        uint256 createdAt,
        bool active
    ) {
        Identity storage identity = identities[account];

        return (
            identity.meshId,
            identity.publicKey,
            identity.createdAt,
            identity.active
        );
    }

    /**
     * @notice Get address for a mesh ID
     * @param meshId Mesh ID to look up
     * @return Address associated with the mesh ID
     */
    function getAddressFromMeshId(bytes32 meshId) external view returns (address) {
        return identityToAddress[meshId];
    }

    /**
     * @notice Verify if an address has a valid identity
     * @param account Address to verify
     * @return True if identity exists and is active, false otherwise
     */
    function hasValidIdentity(address account) external view returns (bool) {
        return identities[account].active;
    }
