```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

contract ResourceVerifier is Ownable, Pausable {
    // Verification request structure
    struct VerificationRequest {
        address contributor;
        string resourceType;
        uint256 amount;
        uint256 startTime;
        uint256 endTime;
        bytes32 proofHash;     // Hash of off-chain verification data
        bool verified;
        uint256 verifiedAt;
    }

    // Storage mappings
    mapping(uint256 => VerificationRequest) public verificationRequests;
    mapping(address => bool) public pendingVerifications;  // Track pending verifications

    // Events
    event VerificationRequested(
        address indexed contributor,
        string resourceType,
        uint256 amount,
        uint256 startTime
    );
    event VerificationCompleted(uint256 indexed requestId, bool verified);

    // Counter for verification requests
    uint256 public requestCounter = 0;

    /**
     * @notice Submit a verification request for resource contribution
     * @param resourceType Type of resource contributed
     * @param amount Amount contributed (scaled by 10^6)
     * @param startTime Start time of contribution
     * @param endTime End time of contribution
     * @param proofHash Hash of off-chain verification data
     */
    function submitVerificationRequest(
        string calldata resourceType,
        uint256 amount,
        uint256 startTime,
        uint256 endTime,
        bytes32 proofHash
    ) external whenNotPaused {
        require(!pendingVerifications[msg.sender], "Already has pending verification");

        requestCounter++;

        VerificationRequest memory request = VerificationRequest({
            contributor: msg.sender,
            resourceType: resourceType,
            amount: amount,
            startTime: startTime,
            endTime: endTime,
            proofHash: proofHash,
            verified: false,
            verifiedAt: 0
        });

        verificationRequests[requestCounter] = request;
        pendingVerifications[msg.sender] = true;

        emit VerificationRequested(msg.sender, resourceType, amount, startTime);
    }

    /**
     * @notice Verify a contribution (admin function)
     * @param requestId ID of the verification request
     */
    function verifyContribution(uint256 requestId) external whenNotPaused onlyOwner {
        VerificationRequest storage request = verificationRequests[requestId];

        require(request.contributor != address(0), "Invalid request ID");
        require(!request.verified, "Already verified");

        // In real implementation would validate the proofHash against off-chain data
        // and check that endTime - startTime equals the claimed duration

        request.verified = true;
        request.verifiedAt = block.timestamp;
        delete pendingVerifications[request.contributor];

        emit VerificationCompleted(requestId, true);
    }

    /**
     * @notice Reject a verification request (admin function)
     * @param requestId ID of the verification request
     */
    function rejectVerification(uint256 requestId) external whenNotPaused onlyOwner {
        VerificationRequest storage request = verificationRequests[requestId];

        require(request.contributor != address(0), "Invalid request ID");
        require(!request.verified, "Already verified");

        delete pendingVerifications[request.contributor];
        emit VerificationCompleted(requestId, false);
    }

    /**
     * @notice Get verification status
     * @param requestId ID of the verification request
     * @return Request details and verification status
     */
    function getVerificationRequest(uint256 requestId) external view returns (
        address contributor,
        string memory resourceType,
        uint256 amount,
        uint256 startTime,
        uint256 endTime,
        bytes32 proofHash,
        bool verified,
        uint256 verifiedAt
    ) {
        VerificationRequest storage request = verificationRequests[requestId];

        return (
            request.contributor,
            request.resourceType,
            request.amount,
            request.startTime,
            request.endTime,
            request.proofHash,
            request.verified,
            request.verifiedAt
        );
    }
}
